@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800&display=swap');
:root{font-family:'Outfit',sans-serif;color:#fff;--pink:#ff8297;--peach:#ffb69e;--ink:#463b56;--glass:rgba(255,249,245,.78);--line:rgba(255,255,255,.72);--mono:'DM Mono',monospace}
