.glass-card{background:var(--glass);color:var(--ink);border:1px solid var(--line);box-shadow:0 8px 32px rgba(80,54,76,.1);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-radius:15px}.hud-left{position:absolute;top:112px;left:40px;width:202px;display:flex;flex-direction:column;gap:10px}.speed-card{padding:16px 17px 13px}.card-label{font:9px var(--mono);letter-spacing:1.15px;color:#897c8e}.tiny-diamond{color:#fb8d91;font-size:8px;margin-right:5px}.speed-readout{display:flex;align-items:baseline;gap:7px;margin:6px 0 0}.speed-readout>span{font-size:52px;font-weight:600;letter-spacing:-3px;line-height:1}.speed-readout small{font:10px var(--mono);letter-spacing:.7px;color:#928494}.speed-track{height:4px;border-radius:5px;background:#e6dfe8;margin:13px 0 8px;overflow:hidden}.speed-track span{height:100%;display:block;width:40%;border-radius:inherit;background:linear-gradient(90deg,#ffb978,#fb8293);transition:width .25s}.speed-foot{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.6px;color:#998e9e}.distance-card{height:62px;padding:10px 13px;display:flex;align-items:center;gap:12px}.metric-icon{width:33px;height:33px;border-radius:10px;background:#ffe8df;color:#ef8c94;display:grid;place-items:center;font-size:18px}.distance-card>div:last-child{display:flex;flex-direction:column;gap:2px}.distance-card strong{font-size:17px;font-weight:600;line-height:1.1}.distance-card strong small{font-size:11px;color:#928494;font-weight:400}.star-icon{color:#eca85c;background:#fff0d9}.score-card{height:60px}
.hud-right{position:absolute;top:112px;right:40px;width:208px;display:flex;flex-direction:column;gap:11px}.traffic-card{padding:15px 15px 12px}.traffic-heading{display:flex;align-items:center;justify-content:space-between}.flow-status{font:8px var(--mono);letter-spacing:.6px;background:#dcf4e3;color:#4b9b70;padding:4px 6px;border-radius:5px}.flow-status.jam{background:#ffdfd8;color:#ce665c}.traffic-meter{position:relative;display:flex;gap:3px;height:8px;margin-top:12px}.traffic-meter span{position:absolute;left:0;top:0;bottom:0;width:25%;border-radius:5px;background:linear-gradient(90deg,#a4dda9,#ffce83,#f78685);transition:width .5s}.traffic-meter i{position:relative;z-index:1;display:block;width:1px;background:rgba(255,255,255,.8)}.traffic-caption{display:flex;justify-content:space-between;margin-top:7px;font:7px var(--mono);letter-spacing:.6px;color:#a49aaa}.mini-map{height:130px;padding:12px 13px 9px}.map-label{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:1px;color:#897c8e}.map-label span{color:#ec9297;font-size:13px}.map-visual{height:72px;margin-top:3px;position:relative;overflow:hidden;background:linear-gradient(110deg,rgba(250,220,211,.4),rgba(223,221,238,.35));border-radius:8px}.map-road{position:absolute;left:42%;top:-21px;height:120px;width:48px;background:#a49cac;transform:rotate(12deg);border-radius:7px}.map-road i{position:absolute;top:0;bottom:0;width:1px;background:rgba(255,255,255,.55)}.map-road i:nth-child(1){left:10px}.map-road i:nth-child(2){left:20px}.map-road i:nth-child(3){left:30px}.map-road i:nth-child(4){left:40px}.map-player,.map-car{position:absolute;z-index:1;width:6px;height:9px;border-radius:3px;background:#ff8297;box-shadow:0 0 5px #fff}.map-player{top:43px;left:51%}.map-car-a{left:43%;top:13px;background:#ffe59c}.map-car-b{left:61%;top:29px;background:#a2e3e3}.map-pin{position:absolute;right:21%;top:8px;color:#fff0a7;text-shadow:0 0 6px #ee9c85;font-size:13px}.map-footer{display:flex;justify-content:space-between;margin-top:7px;font:8px var(--mono);letter-spacing:.7px;color:#a398a6}.map-footer b{color:#ff8794}
.location-pill{position:absolute;left:50%;bottom:82px;transform:translateX(-50%);height:34px;padding:0 14px;display:flex;align-items:center;gap:8px;border:1px solid rgba(255,255,255,.7);border-radius:20px;background:rgba(255,250,247,.7);backdrop-filter:blur(12px);color:#67586f;font:9px var(--mono);letter-spacing:1px;white-space:nowrap;box-shadow:0 4px 18px rgba(76,53,80,.08)}.location-icon{font-size:15px;color:#f28b93}.location-divider{height:13px;width:1px;background:#d8cad5;margin:0 2px}.mission-card{position:absolute;left:40px;bottom:77px;padding:10px 12px;display:flex;align-items:center;gap:10px;min-width:220px;color:var(--ink)}.mission-star{width:30px;height:30px;border-radius:9px;background:#fff0d9;color:#eba552;display:grid;place-items:center;font-size:16px}.mission-card>div:nth-child(2){display:flex;flex-direction:column;gap:2px}.mission-card b{font-size:9px;letter-spacing:.5px}.mission-card span{font-size:10px;color:#948799}.mission-check{margin-left:auto;color:#79bc8f;font-size:15px}.controls-hint{position:absolute;right:40px;bottom:85px;display:flex;align-items:center;gap:5px;color:rgba(255,255,255,.9);font:8px var(--mono);letter-spacing:1px;text-shadow:0 1px 5px rgba(48,39,65,.4)}.keycap{border:1px solid rgba(255,255,255,.65);border-radius:4px;background:rgba(255,255,255,.22);min-width:19px;height:19px;display:grid;place-items:center;font-size:9px}.hint-divider{padding:0 5px;opacity:.65}.bottom-note{position:absolute;bottom:23px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;white-space:nowrap;color:rgba(255,255,255,.92);font:8px var(--mono);letter-spacing:1.3px;text-shadow:0 1px 5px rgba(42,35,59,.4)}.note-sparkle{font-size:12px;color:#ffe1a3}.note-line{width:24px;height:1px;background:rgba(255,255,255,.55)}
.autopilot-toggle{position:absolute;right:40px;bottom:142px;display:flex;align-items:center;gap:9px;text-align:left;border:1px solid rgba(255,255,255,.65);border-radius:13px;background:rgba(255,250,247,.78);color:#51465c;padding:9px 11px;box-shadow:0 6px 24px rgba(72,48,72,.1);backdrop-filter:blur(10px);cursor:pointer}.auto-icon{font-size:19px;color:#ed9297}.autopilot-toggle>span:nth-child(2){display:flex;flex-direction:column;gap:2px}.autopilot-toggle b{font-size:9px;letter-spacing:.7px}.autopilot-toggle small{font:7px var(--mono);color:#9a8fa0;letter-spacing:.3px}.toggle-track{margin-left:5px;width:28px;height:16px;border-radius:10px;background:#d9d3dd;display:flex;align-items:center;padding:2px}.toggle-track i{height:12px;width:12px;border-radius:50%;background:#fff;transition:transform .2s}.autopilot-toggle.active .toggle-track{background:#f4969a}.autopilot-toggle.active .toggle-track i{transform:translateX(12px)}.camera-button{position:absolute;right:40px;bottom:90px;width:42px;height:40px;border:1px solid rgba(255,255,255,.65);border-radius:12px;background:rgba(255,255,255,.2);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;cursor:pointer;backdrop-filter:blur(8px)}.camera-button span{font-size:15px}.camera-button small{font:7px var(--mono);letter-spacing:.5px}.toast{position:absolute;top:94px;left:50%;transform:translate(-50%,-10px);opacity:0;transition:.3s;background:rgba(69,57,79,.78);padding:9px 15px;border-radius:20px;font:10px var(--mono);letter-spacing:.5px;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-overlay{position:absolute;inset:0;z-index:5;display:grid;place-items:center;background:rgba(74,54,75,.22);backdrop-filter:blur(7px)}.hidden{display:none}.pause-panel{padding:32px 38px;text-align:center;color:#51465c;width:min(90vw,370px)}.pause-kicker{font:9px var(--mono);letter-spacing:1.7px;color:#df8f91}.pause-panel h1{font-size:30px;line-height:1.05;margin:12px 0 5px}.pause-panel p{margin:0 0 22px;font-size:13px;color:#948799}.primary-button{background:#f58f99;border:0;border-radius:9px;padding:12px 16px;font-size:10px;letter-spacing:1px;font-weight:700;cursor:pointer}.primary-button span{padding-left:12px}.drive-controls{display:none}
