  const ring = addMesh(group, new THREE.TorusGeometry(.62, .055, 8, 24), mat('#fff0c1', .25, { emissive: '#ffcf74', emissiveIntensity: .8 }), [0, 1.35, 0], [1, 1, 1], [Math.PI / 2, 0, 0]);
