window.addEventListener('resize', resize);
resize(); camera.position.set(-2.5, 9.3, 13.8); camera.lookAt(-1.3, 1, -20);
announce('SCENIC ROUTE OPEN · COLLECT THE GLOWING CHARMS');
requestAnimationFrame(animate);

